<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$views[$view]?> | 35MDBS</title><link rel="stylesheet" href="assets/css/style.css?v=<?=filemtime(__DIR__.'/assets/css/style.css')?>"></head><body><?php require 'template/nav.php';?><main class="container"><section class="panel"><p class="eyebrow">35MDBS / ภาพรวม</p><h1 class="page-title"><?=$views[$view]?></h1><div class="toolbar"><?php foreach($views as $k=>$label):?><a class="btn <?=$k===$view?'btn-primary':'btn-outline'?>" href="?<?=htmlspecialchars(http_build_query(array_merge($_GET,['view'=>$k])))?>"><?=$label?></a><?php endforeach;?></div><?php require 'config/report_filters.php';?><p>ปีงบประมาณนับ ต.ค.–ก.ย. · เงินคงเหลือ = รับสะสม − โอนออก − ส่งคืน − ตัดจ่าย − นำส่ง · วงเงินใช้ได้หักยอดกันไว้/ขอใช้/ผูกพันที่ยังไม่ปลด</p><p>ยอด GF ใช้เฉพาะรายการที่ยืนยันแล้ว ไม่ถือว่ายอดตัดจ่ายเป็นยอด GF โดยอัตโนมัติ</p><div class="toolbar"><button class="btn btn-outline" onclick="window.print()">พิมพ์ตาราง</button><a class="btn btn-success" href="exports/export_overview_35.php?<?=htmlspecialchars(http_build_query(array_merge($_GET,['view'=>$view])))?>">ส่งออกตาราง Excel</a></div></section><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><section class="panel"><div class="table-wrap"><table><thead><tr><th>#</th><th>หน่วย / ศูนย์ต้นทุน / รหัสงบประมาณ</th><?php if($view==='quarter'):foreach(range(1,4) as $q):?><th>Q<?=$q?> รับงบ</th><th>Q<?=$q?> ตัดจ่าย</th><th>Q<?=$q?> ร้อยละ</th><?php endforeach;else:foreach(['เพิ่มในช่วง','โอนไป','ส่งคืน ทบ.','กันไว้','ขอใช้','ผูกพัน','ตัดจ่ายสะสม','นำส่งในช่วง','ยอด GF สะสม','คงเหลือเงินสด','วงเงินใช้ได้','% ตัดจ่าย','% GF'] as $label):?><th><?=$label?></th><?php endforeach;endif;?></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=htmlspecialchars($r['label'])?></td><?php if($view==='quarter'):foreach($r['quarters'] as $q):?><td><?=report_money($q['received'])?></td><td><?=report_money($q['payment'])?></td><td><?=$q['received']>0?number_format($q['payment']/$q['received']*100,2).'%':'—'?></td><?php endforeach;else:foreach(['increase','transfer_out','return_army','carry','request','obligation','payment','remittance','gf_paid','cash','available'] as $key):?><td class="text-right"><?=report_money($r[$key])?></td><?php endforeach;?><td><?=$r['allocated']>0?number_format($r['payment']/$r['allocated']*100,2).'%':'—'?></td><td><?=$r['allocated']>0?number_format($r['gf_paid']/$r['allocated']*100,2).'%':'—'?><?php if($r['gf_unconfirmed']):?><small> ยังไม่ยืนยัน GF <?=report_money($r['gf_unconfirmed'])?></small><?php endif;?></td><?php endif;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="15">ไม่พบข้อมูลตามเงื่อนไข</td></tr><?php endif;?></tbody></table></div><p><?=count($accounts)?> บัญชีคุม · รายการเก่าที่ยังไม่จำแนกหน่วยจะไม่ถูกเดาหน่วยหรือแผนงานให้เอง</p></section><?=document_signatures_html(db_document_signers($conn,is_admin()?(int)($_GET['unit_id']??0):current_unit_id(),'OVERVIEW_35'))?></main></body></html>
